<template>
  <div class="calendar">
    <div class="calendar-header">
      <span class="calendar-header__title">{{ monthName }} {{ year }}</span>
      <button @click="prevMonth" class="calendar-header__btn _prev">
        <img src="~@/assets/img/prev-btn.svg" alt="" />
      </button>
      <button @click="nextMonth" class="calendar-header__btn _next">
        <img src="~@/assets/img/next-btn.svg" alt="" />
      </button>
    </div>
    <div class="calendar-grid">
      <div v-for="day in weekDays" :key="day" class="day-name">{{ day }}</div>

      <div
        v-for="day in days"
        :key="day.date.toISOString()"
        :class="getDayClasses(day)"
        @click="selectDay(day)"
      >
        {{ day.date.getDate() }}
      </div>
    </div>
  </div>
</template>

<script setup lang="ts">
import { ref, computed, defineEmits } from "vue";
import { useStore } from "vuex";

const store = useStore();

const availableDates = computed(() => store.state.availableDates);

const emit = defineEmits<{
  (e: "update:selectedDate", value: Date): void;
}>();

const today = new Date();
const year = ref(today.getFullYear());
const month = ref(today.getMonth());
const selectedDate = ref<Date | null>(null);

const weekDays = ["Пн", "Вт", "Ср", "Чт", "Пт", "Сб", "Вс"];

function getDayClasses(day: { date: Date; isVisible: boolean }) {
  const isoDate = getFormatDate(day.date);
  const isAvailable = availableDates.value.includes(isoDate);

  return {
    day: true,
    available: isAvailable,
    unavailable: !isAvailable && day.isVisible,
    selected: isSelected(day.date),
    _hide: !day.isVisible,
  };
}

const days = computed(() => {
  const firstDate = new Date(year.value, month.value, 1);
  const firstDayOfWeek = (firstDate.getDay() + 6) % 7;

  const totalDays = new Date(year.value, month.value + 1, 0).getDate();
  const result = [];

  for (let i = 0; i < firstDayOfWeek; i++) {
    result.push({ isVisible: false, date: new Date() });
  }
  for (let day = 1; day <= totalDays; day++) {
    const date = new Date(year.value, month.value, day);
    result.push({
      isVisible: true,
      date,
      isAvailable: availableDates.value.includes(getFormatDate(date)),
    });
  }
  return result;
});

const monthName = computed(() => {
  const months = [
    "Январь",
    "Февраль",
    "Март",
    "Апрель",
    "Май",
    "Июнь",
    "Июль",
    "Август",
    "Сентябрь",
    "Октябрь",
    "Ноябрь",
    "Декабрь",
  ];
  return months[month.value];
});

function selectDay(day: { date: Date; isAvailable: boolean }) {
  if (!day.isAvailable) return;
  selectedDate.value = day.date;

  store.state.selectedDate = getFormatDate(day.date);
  store.state.selectedServices = [];
}

function isSelected(date: Date) {
  return selectedDate.value?.toDateString() === date.toDateString();
}

function prevMonth() {
  const today = new Date();
  const currentYear = today.getFullYear();
  const currentMonth = today.getMonth(); // 0 = Январь

  if (year.value === currentYear && month.value <= currentMonth) {
    // Уже текущий месяц, назад нельзя
    return;
  }

  if (month.value === 0) {
    month.value = 11;
    year.value--;
  } else {
    month.value--;
  }
}

function getFormatDate(date: Date) {
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, "0");
  const day = String(date.getDate()).padStart(2, "0");
  return `${year}-${month}-${day}`;
}

function nextMonth() {
  if (month.value === 11) {
    month.value = 0;
    year.value++;
  } else {
    month.value++;
  }
}
</script>

<style scoped lang="scss">
.calendar {
  width: 100%;
  max-width: 634px;
  border: 1px solid #ddd;
  border-radius: 12px;
  padding: 72px 100px;
  background: #fff;

  align-self: flex-start;

  font-size: 24px;

  height: auto;

  @media (max-width: 1100px) {
    font-size: 21px;
    padding: 40px 60px;
    max-width: 570px;
  }
  @media (max-width: 1000px) {
    font-size: 20px;
    padding: 30px 40px;
    max-width: 500px;
  }
  @media (max-width: 560px) {
    font-size: 20px;
    padding: 20px;
    max-width: 100%;
  }
  @media (max-width: 420px) {
    font-size: 17px;
    padding: 10px;
  }

  &-grid {
    display: grid;
    grid-template-columns: repeat(7, 1fr);
    gap: 6px;
  }

  .day-name {
    text-align: center;
    font-weight: 500;
    color: var(--gray-text);
  }

  .day {
    height: 56px;
    width: 56px;
    border-radius: 50%;
    cursor: pointer;
    color: #666;
    display: flex;
    justify-content: center;
    align-items: center;

    transition: 0.1s;

    &.unavailable {
      filter: blur(0.9px);
      opacity: 0.3;
      pointer-events: none;
    }

    @media (max-width: 1100px) {
      width: 45px;
      height: 45px;
    }
    @media (max-width: 420px) {
      width: 35px;
      height: 35px;
    }

    &.available {
      background: var(--light-gray);
    }

    &._hide {
      opacity: 0;
      pointer-events: none;
      position: relative;
    }

    &.selected {
      background: var(--red);
      color: white;
    }
  }
}
.calendar-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 67px;

  &__title {
    font-weight: 600;
    color: var(--gray-text);
    font-size: 22px;
    flex-grow: 1;
  }
  &__btn {
    cursor: pointer;
    padding: 18px 18px 17px 17px;
    height: 15px;
    width: 15px;
    transition: 0.1s;

    border-radius: 2px;

    display: flex;
    justify-content: center;
    align-items: center;

    img {
      display: inline-block;
      width: 17px;
      height: 17px;
    }

    &:hover {
      background-color: rgba(0, 0, 0, 0.04);
    }
    &:active {
      background-color: rgba(0, 0, 0, 0.08);
    }
  }
}
</style>
