<template>
  <form class="register-form" @submit.prevent="handleSubmit">
    <div class="register-form__inner">
      <label class="label-title" for="nameInput">
        Имя<span v-if="errors.name"> ({{ errors.name }})</span>
      </label>
      <input
        class="default-input"
        :class="{ _invalid: errors.name }"
        type="text"
        v-model="form.name"
        placeholder="Имя"
        id="nameInput"
        @blur="validateField('name')"
      />

      <label class="label-title" for="surnameInput">
        Фамилия<span v-if="errors.surname"> ({{ errors.surname }})</span>
      </label>
      <input
        class="default-input"
        :class="{ _invalid: errors.surname }"
        type="text"
        v-model="form.surname"
        placeholder="Фамилия"
        id="surnameInput"
        @blur="validateField('surname')"
      />

      <label class="label-title" for="phoneNumberInput">
        Номер телефона<span v-if="errors.phone"> ({{ errors.phone }})</span>
      </label>
      <MaskInput
        name="phone"
        id="phone"
        class="default-input"
        :class="{ _invalid: errors.phone }"
        type="tel"
        :mask="'+7 ### ### ## ##'"
        placeholder="+7"
        v-model="form.phone"
        @blur="validateField('phone')"
      />

      <div class="checkbox-row">
        <checkInput v-model="form.agree" id="check1" />
        <label for="check1"
          >Я даю согласие на отправку информационно-рекламной рассылки
          организации ИНН 7813635955</label
        >
      </div>

      <div class="checkbox-row">
        <checkInput v-model="form.privacy" id="check2" />
        <label
          >Я предоставляю
          <span class="default-link"
          @click="store.state.showPrivacyPolicy = true"
            >согласие на обработку своих персональных данных</span
          >
          организации ИНН 7813635955
        </label>
      </div>
    </div>

    <button class="big-btn _active" :disabled="!canSubmit">Регистрация</button>
  </form>
</template>

<script lang="ts" setup>
import { computed, reactive } from "vue";
import { useStore } from "vuex";
import checkInput from "@/components/UI/check-input.vue";

const store = useStore();

const form = computed({
  get: () => store.state.formData,
  set: (value) => {
    store.commit("setFormData", value);
  },
});

const errors = reactive({
  name: "",
  surname: "",
  phone: "",
});

const validateField = (field: string) => {
  switch (field) {
    case "name":
      errors.name = form.value.name.trim() ? "" : "обязательно";
      break;
    case "surname":
      errors.surname = form.value.surname.trim() ? "" : "обязательно";
      break;
    case "phone":
      errors.phone = form.value.phone.length >= 14 ? "" : "неверный формат";
      break;
  }
};

const validateAll = () => {
  validateField("name");
  validateField("surname");
  validateField("phone");

  return !errors.name && !errors.surname && !errors.phone;
};

const handleSubmit = () => {
  if (validateAll()) {
    console.log("Форма валидна:", form.value);
    store.dispatch("createOrders");
  }
};

const canSubmit = computed(() => {
  return form.value.agree && form.value.privacy;
});
</script>

<style lang="scss" scoped>
.register-form {
  width: 100%;
  display: flex;
  flex-direction: column;

  &__inner {
    flex-grow: 1;
  }
}

.default-input {
  margin-bottom: 22px;

  &._invalid {
    border: 1px solid red;
  }
}

.checkbox-row {
  display: flex;
  align-items: flex-start;
  gap: 9px;
  margin-bottom: 22px;

  label {
    transform: translateY(1px);
  }
}

.label-title {
  display: block;
  margin-bottom: 6px;

  span {
    color: red;
    font-weight: normal;
    font-size: 12px;
  }
}
</style>
