<template>
  <div class="service-block" v-if="service">
    <div class="service-block__name">{{ getTitlte(service) }}</div>
    <vIncrement
      class="service-block__increment"
      :min="0"
      :max="getIncrementMax(service)"

      @plus="$emit('plus')"
      @minus="$emit('minus')"
    ></vIncrement>
  </div>
</template>

<script lang="ts" setup>
import { useStore } from "vuex";
import vIncrement from "@/components/UI/v-increment.vue";

const store = useStore();
/* eslint-disable-next-line */
const props = defineProps({
  service: Object,
});

function getTitlte(service) {
  const datetime = service.date
  const timePart = datetime.split(" ")[1];
  const title = `${service.service.title} ${timePart.slice(0, 5)}`

  return title
}

function getIncrementMax(service) {
  return service.capacity - service.records_count;
}
</script>

