<template>
  <div class="increment">
    <button class="increment__btn _minus" @click="decrement" :disabled="value <= min">−</button>
    <span class="increment__value">{{ value }}</span>
    <button class="increment__btn _plus" @click="increment" :disabled="value >= max">+</button>
  </div>
</template>

<script lang="ts" setup>
import { onMounted, ref, watchEffect } from 'vue';
import { defineProps, defineEmits } from 'vue';

const props = defineProps<{
  min: number;
  max: number;
  value: number;
}>();

const emit = defineEmits<{
  (e: 'plus'): void;
  (e: 'minus'): void;
}>();

const value = ref(props.min);

const increment = () => {
  if (value.value < props.max) {
    value.value++;
    emit('plus');
  }
};

const decrement = () => {
  if (value.value > props.min) {
    value.value--;
    emit('minus');
  }
};
</script>

<style lang="scss" scoped>
.increment {
  display: inline-flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  min-height: 56px;
  min-width: 125px;
  font-size: 22px;
  border: 1px solid #ebebeb;
  border-radius: 16px;
  padding: 0 14px;

  &__value {
    color: #000;
  }

  &__btn {
    min-width: 21px;
    min-height: 21px;
    display: flex;
    justify-content: center;
    align-items: center;
    color: #fff;
    background: #e51e26;
    border-radius: 50%;
    font-weight: 600;
    line-height: 0;

    &:disabled {
      background: #ccc;
    }
  }
}
</style>
