import { createStore } from "vuex";
import axios from "axios";

export default createStore({
  state: {
    authToken: "Bearer gtcwf654agufy25gsadh",
    salonId: 1268324,
    mainLoader: false,
    selectedCategories: [],
    allCategories: [],
    availableDates: [],
    selectedDate: null,
    availableServices: [],
    formData: {
      name: "",
      surname: "",
      phone: "",
      agree: true,
      privacy: true,
    },

    selectedServices: [],

    privacyPolicy: null,
    showPrivacyPolicy: false,
  },
  getters: {},
  mutations: {
    setSelectedDate(state, date) {
      state.selectedDate = date;
    },
    setAvailableServices(state, events: any) {
      const groupedByDate = events.reduce((acc: any, event: any) => {
        const dateKey = event.date.split(" ")[0];

        if (!acc[dateKey]) {
          acc[dateKey] = [];
        }

        acc[dateKey].push(event);

        return acc;
      }, {});

      state.availableServices = groupedByDate;
    },
    updateFormField(state: any, { field, value }) {
      if (field in state.formData) {
        state.formData[field] = value;
      }
    },
  },
  actions: {
    async getAvailableDates(context) {
      return await axios({
        url: `https://api.yclients.com/api/v1/activity/${context.state.salonId}/search_dates?from=2025-04-29&till=9999-01-01&service_ids%5B%5D=19260018,19260019`,
        headers: {
          Authorization: context.state.authToken,
        },
      }).then((res) => {
        context.state.availableDates = res.data.data;
      });
    },
    async getAvaliableServices(context) {
      return await axios({
        method: "GET",
        url: `https://api.yclients.com/api/v1/activity/${context.state.salonId}/search?count=1000&from=2025-04-29&till=9999-01-01&page=1&service_ids%5B%5D=19260018,19260019`,

        headers: {
          Authorization: context.state.authToken,
        },
      }).then((res) => {
        context.commit("setAvailableServices", res.data.data);
      });
    },
    async createOrders(context) {
      const selectedServices = context.state.selectedServices;
      const formData = context.state.formData;
      const orderData = {
        fullname: formData.name,
        surname: formData.surname,
        phone: formData.phone,
        is_personal_data_processing_allowed: true,
        clients_count: null,
        is_charge_required_priority: true,
        is_newsletter_allowed: true,
        is_support_charge: true,
      };

      const createOrderPromises = selectedServices.map(
        (selectedService: any, index) => {
          return new Promise((resolve: any) => {
            setTimeout(() => {
              context.dispatch("createOrder", {
                orderData: {
                  ...orderData,
                  appointments: [
                    {
                      activityId: selectedService.service.id,
                      clients_count: selectedService.clientsCount,
                    },
                  ],
                },
                activity_id: selectedService.service.id,
              });
              resolve();
            }, index * 200);
          });
        }
      );

      Promise.all([createOrderPromises]).finally(() => {
        console.log("Все записи созданы");
      });
    },
    async createOrder(context, { orderData, activity_id }) {
      return await axios({
        url: `https://api.yclients.com/api/v1/activity/${context.state.salonId}/${activity_id}/book`,
        method: "POST",
        data: orderData,
        headers: {
          Authorization: context.state.authToken,
        },
      });
    },
    async getPrivacyPolicy(context:any) {
      return await axios({
        method: 'get',
        url: 'https://api.yclients.com/api/v1/booking/locations/1268324/privacy_policy',
        headers: {
          Authorization: context.state.authToken,
        },
      }).then((res) => {
        context.state.privacyPolicy = res.data.data
      })
    }
  },
  modules: {},
});
