<template>
  <div class="privacy-policy" v-if="privacyPolicy">
    <div class="privacy-policy__inner">
      <button class="close-button" @click="closePrivacyPolicy">×</button>
      <h2
        class="tit-h3"
        v-html="privacyPolicy.attributes.legal_entity_name"
      ></h2>
      <p>ИНН {{ privacyPolicy.id }}</p>

      <div
        class="privacy-policy__content"
        v-html="privacyPolicy.attributes.privacy_agreement_content"
      ></div>
    </div>
    <br />
    <br />

    <button class="big-btn" @click="closePrivacyPolicy">Закрыть</button>
  </div>
</template>

<script lang="ts" setup>
import { computed, onMounted, onUnmounted, watch } from "vue";
import { useStore } from "vuex";

const store = useStore();

const privacyPolicy = computed(() => store.state.privacyPolicy);

const closePrivacyPolicy = () => {
  store.state.showPrivacyPolicy = false;
};

const showPrivacyPolicy = computed(() => store.state.showPrivacyPolicy)

watch(showPrivacyPolicy, (newValue) => {
  if (newValue) {
    parent.postMessage({ type: "scrollTopIframe" }, "*");
    console.log('scrollTopIframe')
  } else {
    parent.postMessage({ type: "scrollBottomIframe" }, "*");
    console.log('scrollBottomIframe')
  }
});
</script>

<style lang="scss" scoped>
.privacy-policy {
  height: 100%;
  position: relative;
  padding: 40px 20px;
  border-radius: 8px;

  &__inner {
  }
}

.close-button {
  position: absolute;
  right: -10px;
  top: -10px;
  background: none;
  border: none;
  font-size: 100px;
  color: var(--main-red);
  cursor: pointer;
  outline: none;
  padding: 20px;
  z-index: 2;
  line-height: 0.2;
}

.close-button:hover {
  color: darkred;
}
</style>
<style lang="scss">
.privacy-policy {
  font-size: 16px;
  li {
    margin-bottom: 10px;
  }
  .tit-h3 {
    margin-bottom: 20px;
  }
}
</style>
