<template>
  <div class="container" :class="{ 'main-loading': mainLoader }">
    <div class="loader" v-show="mainLoader"></div>
    <mainPage v-show="!showPrivacyPolicy && !mainLoader"></mainPage>

    <privacy-policy v-show="showPrivacyPolicy"></privacy-policy>
  </div>
</template>

<script setup>
import mainPage from "@/components/main-page.vue";
import { computed, onMounted } from "vue";
import { useStore } from "vuex";
import privacyPolicy from "@/components/privacy-policy.vue";

const store = useStore();

const showPrivacyPolicy = computed(() => store.state.showPrivacyPolicy);

const mainLoader = computed(() => store.state.mainLoader)

onMounted(() => {
  store.state.mainLoader = true
  store.dispatch("getAvailableDates").then(() => {
    store.dispatch("getAvaliableServices").then(() => {
      store.dispatch("getPrivacyPolicy").then(() => {
        store.state.mainLoader = false
      })
    });
  });
});
</script>

