import { createApp } from "vue";
import App from "./App.vue";
import router from "./router";
import store from "./store";
import "@/assets/fonts/stylesheet.css";
import { MaskInput } from "vue-3-mask";

createApp(App)
  .use(store)
  .component("MaskInput", MaskInput)
  .use(router)
  .mount("#app");
